const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const point1 = ee.Geometry.Point([136.025799, 33.710618]); // Note: GEE uses [lon, lat]
  const point2 = ee.Geometry.Point([136.367495, 33.884848]);
  const date = '2018-09-15';

  // Buffer for area reduction (500m buffer for MODIS 250m/500m resolution)
  const buffer = 500;
  const region1 = point1.buffer(buffer);
  const region2 = point2.buffer(buffer);

  // 2. Data Acquisition - MODIS Terra Surface Reflectance (MOD09GA)
  // Using bands 1 (red) for turbidity estimation
  const modisCol = ee.ImageCollection('MODIS/006/MOD09GA')
    .filterDate(date, ee.Date(date).advance(1, 'day'))
    .select(['sur_refl_b01', 'sur_refl_state_1km']);

  // Check collection size
  const count = modisCol.size().getInfo();
  if (count === 0) {
    print("No MODIS images found for 2018-09-15.");
    print("C1");
    return;
  }

  // Get the single image for the day
  const image = modisCol.first();

  // 3. Cloud masking using state band (bits 0-1: cloud state)
  const cloudMask = image.select('sur_refl_state_1km')
    .bitwiseAnd(3)  // Get cloud state bits
    .eq(0);         // 0 = clear, 1/2/3 = cloudy

  // Apply mask and select red band (higher reflectance = more turbidity)
  const masked = image.select('sur_refl_b01')
    .updateMask(cloudMask)
    .multiply(0.0001);  // Scale factor for MOD09GA

  // 4. Calculate mean reflectance for each region
  const reducer = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = masked.reduceRegion({
    reducer: reducer,
    geometry: region1,
    scale: 500,  // MODIS resolution
    maxPixels: 1e9,
    bestEffort: true
  });

  const stats2 = masked.reduceRegion({
    reducer: reducer,
    geometry: region2,
    scale: 500,
    maxPixels: 1e9,
    bestEffort: true
  });

  const mean1 = stats1.get('sur_refl_b01_mean').getInfo();
  const count1 = stats1.get('sur_refl_b01_count').getInfo();
  const mean2 = stats2.get('sur_refl_b01_mean').getInfo();
  const count2 = stats2.get('sur_refl_b01_count').getInfo();

  print(`Point1: Mean=${mean1?.toFixed(4)}, Pixels=${count1}`);
  print(`Point2: Mean=${mean2?.toFixed(4)}, Pixels=${count2}`);

  // 5. Validation checks
  if (count1 === 0 || count2 === 0) {
    print("C2");
    return;
  }

  if (mean1 === null || mean2 === null || 
      isNaN(mean1) || isNaN(mean2) ||
      mean1 < 0 || mean1 > 1 || 
      mean2 < 0 || mean2 > 1) {
    print("C3");
    return;
  }

  // 6. Final comparison (higher red reflectance = more turbidity)
  const turbidityDiff = mean1 - mean2;
  print(`Turbidity difference: ${turbidityDiff.toFixed(4)}`);

  if (turbidityDiff > 0) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
